<label>Program Kerja<select name="id_proker" required><?php foreach($proker as $p): ?><option value="<?= $p['id_proker'] ?>"><?= htmlspecialchars($p['nama_proker']) ?></option><?php endforeach; ?></select></label>
<label>Jenis Dokumen<input name="jenis_dokumen" placeholder="Proposal / LPJ / Presensi" required></label><label>Nama Dokumen<input name="nama_dokumen" required></label><label>Tanggal Dokumen<input type="date" name="tanggal_dokumen"></label>
<label>Status<select name="status_dokumen"><option>Draft</option><option>Final</option></select></label><label>Tautan Google Drive<input type="url" name="tautan_drive" placeholder="https://drive.google.com/..." required></label><div><button class="btn">Simpan Dokumen</button></div></form></section>
<form class="filter" method="get"><input type="hidden" name="url" value="dokumen/index"><input name="q" placeholder="Cari nama dokumen, proker, divisi..." value="<?= htmlspecialchars($_GET['q'] ?? '') ?>"><input name="jenis" placeholder="Jenis dokumen" value="<?= htmlspecialchars($_GET['jenis'] ?? '') ?>"><button class="btn secondary">Cari / Filter</button></form>
<div class="table-wrap"><table><tr><th>Nama Dokumen</th><th>Program Kerja</th><th>Divisi</th><th>Jenis</th><th>Tanggal</th><th>Status</th><th>Drive</th><th>Aksi</th></tr>
<?php foreach($rows as $r): ?><tr><td><?= htmlspecialchars($r['nama_dokumen']) ?></td><td><?= htmlspecialchars($r['nama_proker']) ?></td><td><?= htmlspecialchars($r['nama_divisi']) ?></td><td><?= htmlspecialchars($r['jenis_dokumen']) ?></td><td><?= htmlspecialchars($r['tanggal_dokumen'] ?? '-') ?></td><td><span class="pill"><?= htmlspecialchars($r['status_dokumen']) ?></span></td><td><a target="_blank" rel="noopener noreferrer" href="<?= htmlspecialchars($r['tautan_drive']) ?>">Buka Drive</a></td><td><form method="post" action="<?= BASE_URL ?>/index.php?url=dokumen/delete" onsubmit="return confirm('Hapus metadata dokumen?')"><input type="hidden" name="id" value="<?= $r['id_dokumen'] ?>"><button class="btn danger">Hapus</button></form></td></tr><?php endforeach; ?></table></div>